import java.nio.file.*;import java.util.*;import java.util.jar.*;import java.io.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class DefaultStateAudit {
 static InsnList ins;static Frame[] frames;
 static String value(SourceValue v,Set<AbstractInsnNode> seen){if(v==null)return "NULL";if(v.insns.size()!=1){Set<String> branches=new TreeSet<>();for(AbstractInsnNode part:v.insns)branches.add(value(new SourceValue(v.getSize(),part),new HashSet<>(seen)));return "MERGE"+branches;}AbstractInsnNode n=v.insns.iterator().next();if(!seen.add(n))return "LOOP";int i=ins.indexOf(n);Frame f=frames[i];int op=n.getOpcode();
  if(n instanceof VarInsnNode){VarInsnNode x=(VarInsnNode)n;if(op==Opcodes.ALOAD){if(x.var==0)return "THIS";if(((SourceValue)f.getLocal(x.var)).insns.isEmpty())return "PARAM"+x.var;return value((SourceValue)f.getLocal(x.var),seen);}if(op==Opcodes.ASTORE)return value((SourceValue)f.getStack(f.getStackSize()-1),seen);}
  if(n instanceof FieldInsnNode){FieldInsnNode x=(FieldInsnNode)n;return x.owner+"."+x.name+"("+(op==Opcodes.GETFIELD?value((SourceValue)f.getStack(f.getStackSize()-1),seen):"STATIC")+")";}
  if(n instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)n;int argc=Type.getArgumentTypes(x.desc).length;return x.name+"("+(op==Opcodes.INVOKESTATIC?"STATIC":value((SourceValue)f.getStack(f.getStackSize()-argc-1),seen))+")";}
  if(op==Opcodes.CHECKCAST)return value((SourceValue)f.getStack(f.getStackSize()-1),seen);
  return "OP"+op;
 }
 public static void main(String[]a)throws Exception{int count=0;for(String p:new String(Files.readAllBytes(Paths.get(a[0]))).trim().split(":")){if(!p.endsWith(".jar")||!Files.exists(Paths.get(p)))continue;try(JarFile j=new JarFile(p)){Enumeration<JarEntry> es=j.entries();while(es.hasMoreElements()){JarEntry e=es.nextElement();if(!e.getName().endsWith(".class"))continue;try(InputStream in=j.getInputStream(e)){ClassNode c=new ClassNode();new ClassReader(in).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(Object mo:c.methods){MethodNode m=(MethodNode)mo;for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)n;if(x.name.equals("<init>")&&(x.owner.contains("BlockState")||x.owner.contains("ExtendedBlockState"))&&x.desc.startsWith("(Lnet/minecraft/block/Block;")){ins=m.instructions;frames=new Analyzer(new SourceInterpreter()).analyze(c.name,m);Frame f=frames[ins.indexOf(n)];int argc=Type.getArgumentTypes(x.desc).length;String arg=value((SourceValue)f.getStack(f.getStackSize()-argc),new HashSet<>());System.err.println("CONTAINER\t"+c.name+"\t"+m.name+"\t"+x.owner+"\t"+arg);}
if((x.name.equals("setDefaultState")||x.name.equals("func_180632_j"))&&x.desc.equals("(Lnet/minecraft/block/state/IBlockState;)V")){ins=m.instructions;frames=new Analyzer(new SourceInterpreter()).analyze(c.name,m);Frame f=frames[ins.indexOf(n)];String recv=value((SourceValue)f.getStack(f.getStackSize()-2),new HashSet<>()),arg=value((SourceValue)f.getStack(f.getStackSize()-1),new HashSet<>());System.out.println(c.name+"\t"+m.name+"\t"+recv+"\t"+arg);count++;}}}}}}}System.err.println("setDefaultState sites "+count);}
}
